import{_ as n,C as s,o as c,c as l,a2 as d,E as t,j as o,a as i}from"./chunks/framework.TaNiW7i8.js";const f=JSON.parse('{"title":"Archive and session","description":"","frontmatter":{"title":"Archive and session"},"headers":[],"relativePath":"en/reference/mcp/session.md","filePath":"en/reference/mcp/session.md"}'),u={name:"en/reference/mcp/session.md"};function h(m,e,p,_,v,b){const a=s("AskExample"),r=s("McpResume");return c(),l("div",null,[e[0]||(e[0]=d('<h1 id="archive-and-session" tabindex="-1">Archive and session <a class="header-anchor" href="#archive-and-session" aria-label="Permalink to &quot;Archive and session&quot;">​</a></h1><p>These tools handle <strong>the life of a work session</strong>: archive it, cancel the last archive, shelve a finished project, set a project&#39;s phase or summary, keep the week&#39;s worklog.</p><p>They <strong>write to the vault</strong>, except <code>mem_archive_rewrite_paths</code>, which only rewrites when <code>confirm</code> is true (without it, it is a dry run). <code>mem_worklog</code> also writes, but only in its <code>persist</code> phase: its <code>collect</code> phase, the default, is read-only. <code>mem_rollback_archive</code> deletes the last archive and its <code>history.md</code> entry; <code>context.md</code> is not restored.</p><p>To ask for them by talking to your agent, see <a href="/Kessho/en/agent/archiver.html">Archive a session</a>.</p><h2 id="in-practice" tabindex="-1">In practice <a class="header-anchor" href="#in-practice" aria-label="Permalink to &quot;In practice&quot;">​</a></h2>',5)),t(a,{tool:"mem_archive"}),t(a,{tool:"mem_set_summary"}),e[1]||(e[1]=o("h2",{id:"the-tools",tabindex:"-1"},[i("The tools "),o("a",{class:"header-anchor",href:"#the-tools","aria-label":'Permalink to "The tools"'},"​")],-1)),e[2]||(e[2]=o("h2",{id:"mem-archive",tabindex:"-1"},[o("code",null,"mem_archive"),i(),o("a",{class:"header-anchor",href:"#mem-archive","aria-label":'Permalink to "`mem_archive`"'},"​")],-1)),t(r,{tool:"mem_archive"}),e[3]||(e[3]=d('<p>Archive une session. Mode incrémental : réécrit context.md seul, en cours de session. Mode complet : crée une archive horodatée, préfixe history.md et réinitialise context.md.</p><table tabindex="0"><thead><tr><th>Paramètre / Parameter</th><th>Type</th><th>Requis / Required</th><th>Description (catalogue)</th></tr></thead><tbody><tr><td><code>archive_aliases</code></td><td>array&lt;string&gt;</td><td>non / no</td><td>Mode complet : autres mots par lesquels cette archive sera cherchée plus tard — le vocabulaire VÉCU, pas celui du correctif (« barre de menus » pour systray, « l&#39;app est toute blanche » pour un écran vide). Écrits en <code>aliases</code>, clé de frontmatter répandue (Obsidian la lit aussi), et pesés comme une désignation au classement de mem_search.</td></tr><tr><td><code>archive_body_md</code></td><td>string</td><td>non / no</td><td>Mode complet : corps de l&#39;archive.</td></tr><tr><td><code>archive_extra_fm</code></td><td>object</td><td>non / no</td><td>Frontmatter additionnel fusionné à celui de l&#39;archive : les listes <code>tags</code> sont concaténées sans doublon, toute autre clé est remplacée. Le paramètre était accepté sans être déclaré — donc indécouvrable.</td></tr><tr><td><code>archive_subject</code></td><td>string</td><td>non / no</td><td>Mode complet : sujet court de l&#39;archive.</td></tr><tr><td><code>context_md</code></td><td>string</td><td>non / no</td><td>Nouveau corps de context.md, qui REMPLACE l&#39;actuel. Omis (ou null) : le corps actuel est gardé tel quel — c&#39;est ainsi qu&#39;on ajoute une archive ou pose une phase sans toucher au contexte. Une chaîne vide ou faite d&#39;espaces est refusée, rien n&#39;est écrit : pour garder le contexte, omettre le champ.</td></tr><tr><td><code>derive</code></td><td>array&lt;object&gt;</td><td>non / no</td><td>Mode complet : les faits durables à ÉCRIRE comme atomes curatés. L&#39;outil les crée dans leur zone, pose le lien retour vers cette session, et ajoute leurs wikiliens à derived_atoms — un seul appel au lieu d&#39;un par fait. Un nom déjà pris fait REFUSER l&#39;archivage en entier, sans suffixe ni écrasement.</td></tr><tr><td><code>derive[].body</code></td><td>string</td><td>oui / yes</td><td>Pourquoi il est vrai, et ce que coûte de l&#39;ignorer.</td></tr><tr><td><code>derive[].fact</code></td><td>string</td><td>oui / yes</td><td>Le fait, qui nomme l&#39;atome et par lequel on le retrouvera.</td></tr><tr><td><code>derive[].kind</code></td><td>string</td><td>oui / yes</td><td>principle | goal | knowledge — les trois zones curatées.</td></tr><tr><td><code>derived_atoms</code></td><td>array&lt;string&gt;</td><td>non / no</td><td>Mode complet, OBLIGATOIRE sauf si no_derived_because est donné : ce que la session laisse de durable — un principe qui contraindra le travail futur, un but posé ou changé, une connaissance qui a coûté à acquérir. Un fait resté dans une archive se retrouve en 4 à 6 tentatives, contre 1 à 3 pour un atome curaté.</td></tr><tr><td><code>expect_decisions</code></td><td>array&lt;string&gt;</td><td>non / no</td><td>Décisions cumulatives devant survivre au nouveau corps.</td></tr><tr><td><code>mode</code></td><td>string</td><td>non / no</td><td>&#39;incremental&#39; (défaut) ou &#39;full&#39;.</td></tr><tr><td><code>no_derived_because</code></td><td>string</td><td>non / no</td><td>Mode complet, OBLIGATOIRE si et seulement si derived_atoms est vide : pourquoi cette session ne laisse rien de durable. Un simple « rien de durable ce soir » suffit — ce qui est refusé est le SILENCE, pas la brièveté. Une question sautée est indiscernable d&#39;une réponse vide.</td></tr><tr><td><code>phase</code></td><td>string</td><td>non / no</td><td>Nouvelle phase, écrite seulement si fournie.</td></tr><tr><td><code>slug</code></td><td>string</td><td>oui / yes</td><td>Slug du projet ou domaine.</td></tr><tr><td><code>source_hint</code></td><td>string</td><td>non / no</td><td>&#39;archeo-git&#39; pour valider le frontmatter d&#39;archive archéo.</td></tr></tbody></table><h2 id="mem-rollback-archive" tabindex="-1"><code>mem_rollback_archive</code> <a class="header-anchor" href="#mem-rollback-archive" aria-label="Permalink to &quot;`mem_rollback_archive`&quot;">​</a></h2>',3)),t(r,{tool:"mem_rollback_archive"}),e[4]||(e[4]=d('<p>Annule la dernière archive d&#39;un projet : la supprime et retire sa ligne de history.md. context.md n&#39;est pas restauré.</p><table tabindex="0"><thead><tr><th>Paramètre / Parameter</th><th>Type</th><th>Requis / Required</th><th>Description (catalogue)</th></tr></thead><tbody><tr><td><code>slug</code></td><td>string</td><td>oui / yes</td><td>Slug du projet ou domaine.</td></tr></tbody></table><h2 id="mem-historize" tabindex="-1"><code>mem_historize</code> <a class="header-anchor" href="#mem-historize" aria-label="Permalink to &quot;`mem_historize`&quot;">​</a></h2>',3)),t(r,{tool:"mem_historize"}),e[5]||(e[5]=d('<p>Déplace un projet terminé vers 10-episodes/archived/, ou l&#39;en ramène avec revive. Corrige la phase, archived_at et le suffixe d&#39;affichage.</p><table tabindex="0"><thead><tr><th>Paramètre / Parameter</th><th>Type</th><th>Requis / Required</th><th>Description (catalogue)</th></tr></thead><tbody><tr><td><code>revive</code></td><td>boolean</td><td>non / no</td><td>Ramener le projet parmi les actifs.</td></tr><tr><td><code>slug</code></td><td>string</td><td>oui / yes</td><td>Slug du projet.</td></tr></tbody></table><h2 id="mem-update-phase" tabindex="-1"><code>mem_update_phase</code> <a class="header-anchor" href="#mem-update-phase" aria-label="Permalink to &quot;`mem_update_phase`&quot;">​</a></h2>',3)),t(r,{tool:"mem_update_phase"}),e[6]||(e[6]=d('<p>Met à jour la phase du context.md d&#39;un projet en préservant son corps mot pour mot. Une chaîne vide efface la phase.</p><table tabindex="0"><thead><tr><th>Paramètre / Parameter</th><th>Type</th><th>Requis / Required</th><th>Description (catalogue)</th></tr></thead><tbody><tr><td><code>phase</code></td><td>string</td><td>oui / yes</td><td>Nouvelle phase. Chaîne vide pour l&#39;effacer.</td></tr><tr><td><code>slug</code></td><td>string</td><td>oui / yes</td><td>Slug du projet ou domaine.</td></tr></tbody></table><h2 id="mem-set-summary" tabindex="-1"><code>mem_set_summary</code> <a class="header-anchor" href="#mem-set-summary" aria-label="Permalink to &quot;`mem_set_summary`&quot;">​</a></h2>',3)),t(r,{tool:"mem_set_summary"}),e[7]||(e[7]=d('<p>Pose le résumé court d&#39;un projet ou domaine dans le frontmatter de son context.md, en préservant le reste du fichier. À appeler après chaque archivage ou point de contrôle mémoriel. Le résumé est ÉCRIT par l&#39;agent : le vault ne sait pas le deviner, et aucune extraction n&#39;est fiable. Borné à 300 caractères — un champ libre sans borne devient un journal.</p><table tabindex="0"><thead><tr><th>Paramètre / Parameter</th><th>Type</th><th>Requis / Required</th><th>Description (catalogue)</th></tr></thead><tbody><tr><td><code>slug</code></td><td>string</td><td>oui / yes</td><td>Slug du projet ou domaine.</td></tr><tr><td><code>summary</code></td><td>string</td><td>oui / yes</td><td>Le résumé, en une phrase ou deux. 300 caractères au plus. Les retours à la ligne sont écrasés.</td></tr></tbody></table><h2 id="mem-worklog" tabindex="-1"><code>mem_worklog</code> <a class="header-anchor" href="#mem-worklog" aria-label="Permalink to &quot;`mem_worklog`&quot;">​</a></h2>',3)),t(r,{tool:"mem_worklog"}),e[8]||(e[8]=d('<p>Rassemble les archives de la semaine ISO et leur proration horaire. Phase collect en lecture seule, phase persist écrit le worklog en trois niveaux de verbosité.</p><table tabindex="0"><thead><tr><th>Paramètre / Parameter</th><th>Type</th><th>Requis / Required</th><th>Description (catalogue)</th></tr></thead><tbody><tr><td><code>amplitude_hours</code></td><td>number</td><td>non / no</td><td>Heures travaillées par jour (défaut 7).</td></tr><tr><td><code>brief_md</code></td><td>string</td><td>non / no</td><td></td></tr><tr><td><code>detailed_md</code></td><td>string</td><td>non / no</td><td></td></tr><tr><td><code>digest_md</code></td><td>string</td><td>non / no</td><td></td></tr><tr><td><code>include_weekend</code></td><td>boolean</td><td>non / no</td><td>Inclure samedi et dimanche.</td></tr><tr><td><code>phase</code></td><td>string</td><td>non / no</td><td>&#39;collect&#39; (défaut) ou &#39;persist&#39;.</td></tr><tr><td><code>week_of</code></td><td>string</td><td>non / no</td><td>Date d&#39;ancrage AAAA-MM-JJ. Vide : aujourd&#39;hui.</td></tr></tbody></table><h2 id="mem-archive-rewrite-paths" tabindex="-1"><code>mem_archive_rewrite_paths</code> <a class="header-anchor" href="#mem-archive-rewrite-paths" aria-label="Permalink to &quot;`mem_archive_rewrite_paths`&quot;">​</a></h2>',3)),t(r,{tool:"mem_archive_rewrite_paths"}),e[9]||(e[9]=d('<p>Réécrit les chemins absolus des archives d&#39;un projet en sigils &lt;repo&gt;/… . Essai à blanc par défaut.</p><table tabindex="0"><thead><tr><th>Paramètre / Parameter</th><th>Type</th><th>Requis / Required</th><th>Description (catalogue)</th></tr></thead><tbody><tr><td><code>confirm</code></td><td>boolean</td><td>non / no</td><td>Sans confirm, l&#39;appel est un essai à blanc.</td></tr><tr><td><code>include_context_history</code></td><td>boolean</td><td>non / no</td><td>Réécrire aussi context.md et history.md (défaut vrai).</td></tr><tr><td><code>old_root</code></td><td>string</td><td>non / no</td><td>Ancienne racine absolue. Défaut : le repo_path courant.</td></tr><tr><td><code>slug</code></td><td>string</td><td>oui / yes</td><td>Slug du projet.</td></tr></tbody></table>',2))])}const T=n(u,[["render",h]]);export{f as __pageData,T as default};
